import React from 'react';
import Hero from './Hero';
import Features from './Features';

export default function Home({ setCurrentPage }) {
  return (
    <div>
      <Hero setCurrentPage={setCurrentPage} />
      
      {/* Professional Stats Banner */}
      <div style={{ backgroundColor: '#0b2915', color: '#fff', padding: '35px 20px', borderTop: '1px solid #1e5a30', borderBottom: '1px solid #1e5a30' }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap', gap: '20px', textAlign: 'center' }}>
          <div>
            <h2 style={{ fontSize: '36px', margin: '0 0 5px 0', color: '#4ade80', fontWeight: 'bold' }}>9+</h2>
            <p style={{ margin: 0, fontSize: '14px', color: '#94a3b8', fontWeight: '500' }}>Expert Subject Teachers</p>
          </div>
          <div>
            <h2 style={{ fontSize: '36px', margin: '0 0 5px 0', color: '#4ade80', fontWeight: 'bold' }}>Modern</h2>
            <p style={{ margin: 0, fontSize: '14px', color: '#94a3b8', fontWeight: '500' }}>Physical & Digital Classrooms</p>
          </div>
          <div>
            <h2 style={{ fontSize: '36px', margin: '0 0 5px 0', color: '#4ade80', fontWeight: 'bold' }}>100%</h2>
            <p style={{ margin: 0, fontSize: '14px', color: '#94a3b8', fontWeight: '500' }}>Individual Student Attention</p>
          </div>
        </div>
      </div>

      <Features />
    </div>
  );
}
